<script>const customer=document.getElementById('customer_party_id'),body=document.getElementById('advance-sources');async function loadSources(){body.replaceChildren();const r=await fetch('{{ route('accounting.customer-advance-returns.sources') }}?party_id='+encodeURIComponent(customer.value));const j=await r.json();for(const s of j.sources||[]){const tr=document.createElement('tr');tr.innerHTML='<td>'+s.source_number+'</td><td>'+s.advance_source_type+'</td><td>'+s.source_date+'</td><td>'+(s.booking_id||'')+'</td><td>'+s.original_amount.toFixed(2)+'</td><td>'+(s.original_amount-s.available_amount).toFixed(2)+'</td><td>0.00</td><td>'+s.available_amount.toFixed(2)+'</td><td><input type="number" step="0.01" min="0" max="'+s.available_amount+'" name="allocations['+body.children.length+'][amount]" data-available="'+s.available_amount+'"><input type="hidden" name="allocations['+body.children.length+'][advance_source_type]" value="'+s.advance_source_type+'"><input type="hidden" name="allocations['+body.children.length+'][advance_source_id]" value="'+s.advance_source_id+'"></td>';body.append(tr)}updateTotals()}function updateTotals(){let selected=0,available=0;body.querySelectorAll('input[type=number]').forEach(i=>{selected+=Number(i.value||0);available+=Number(i.dataset.available||0)});document.getElementById('available-total').value=available.toFixed(2);document.getElementById('selected-total').value=selected.toFixed(2);document.getElementById('remaining-total').value=(available-selected).toFixed(2);document.getElementById('return-amount').value=selected.toFixed(2)}customer.addEventListener('change',loadSources);body.addEventListener('input',updateTotals);loadSources();</script>
